package com.greenlink.controller;import com.greenlink.dto.RatingView;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.RatingService;import java.util.*;import org.bson.types.ObjectId;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ratings") public class RatingController {private final RatingService s;public RatingController(RatingService s){this.s=s;} @PostMapping public ResponseEntity<RatingView> create(@AuthenticationPrincipal AppUserPrincipal p,@RequestBody Map<String,Object> b){return ResponseEntity.status(201).body(s.create(new ObjectId(p.getId()),(String)b.get("requestId"),Integer.parseInt(b.get("rating").toString()),(String)b.getOrDefault("comment","")));} @GetMapping("/provider/{providerId}") public Map<String,Object> provider(@PathVariable String providerId){return s.provider(new ObjectId(providerId));}}
